CREATE TABLE sessions (
  id          TEXT PRIMARY KEY,
  title       TEXT,
  origin      TEXT,                -- web_claude_ai | claude_code_cli | cowork-* | local
  surface     TEXT,                -- claude-code | cowork | web
  project     TEXT,
  model       TEXT,
  started     TEXT,
  ended       TEXT,
  input       INTEGER DEFAULT 0,
  cache_write INTEGER DEFAULT 0,
  cache_read  INTEGER DEFAULT 0,
  output      INTEGER DEFAULT 0,
  cost        REAL DEFAULT 0,
  context_used   INTEGER,
  context_max    INTEGER,
  harvested   INTEGER NOT NULL DEFAULT 0,   -- 1 = came from the session API
  raw         TEXT
);
INSERT INTO "sessions" VALUES('legacy-cloud','Synthetic harvested title','web_claude_ai','web',NULL,'claude-opus-5','2026-09-15T17:00:00+00:00','2026-09-15T17:30:00+00:00',503,31,47,59,12.345,NULL,NULL,1,'{"id":"legacy-cloud","title":"Synthetic harvested title","origin":"web_claude_ai","environment_kind":"anthropic_cloud","created_at":"2026-09-15T17:00:00+00:00","updated_at":"2026-09-15T17:30:00+00:00","session_context":{"model":"claude-opus-5"},"external_metadata":{"usage":{"input_tokens":503,"cache_write_tokens":31,"cache_read_tokens":47,"output_tokens":59,"cost_usd":12.345}}}');
CREATE TABLE titles (
  session   TEXT PRIMARY KEY,
  kind      TEXT NOT NULL,
  rank      INTEGER NOT NULL,
  ts        TEXT,
  text      TEXT NOT NULL
);
