CREATE INDEX turns_day ON turns(day);
CREATE INDEX turns_session ON turns(session);
CREATE INDEX turns_model ON turns(model);
CREATE INDEX sessions_started ON sessions(started);
CREATE INDEX findings_scope ON findings(scope, active);
CREATE INDEX turns_hr ON turns(substr(ts, 1, 13));
CREATE INDEX rollup_day ON rollup(day);
CREATE INDEX rollup_hr ON rollup(hr);
CREATE INDEX quota_samples_series ON quota_samples(key, scope, ts);
CREATE INDEX raw_lines_hr ON raw_lines(hr);
